draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw street
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, H/2);
  ctx.lineTo(W, H/2);
  ctx.stroke();

  // draw dog
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(100 + 50 * Math.sin(t), H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(100 + 50 * Math.sin(t), H/2 - 30);
  ctx.lineTo(100 + 50 * Math.sin(t), H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(100 + 50 * Math.sin(t), H/2 - 10);
  ctx.lineTo(80 + 50 * Math.sin(t), H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(100 + 50 * Math.sin(t), H/2 - 10);
  ctx.lineTo(120 + 50 * Math.sin(t), H/2 + 10);
  ctx.stroke();

  // draw blind person
  ctx.beginPath();
  ctx.arc(200 + 20 * Math.sin(t), H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(200 + 20 * Math.sin(t), H/2 - 30);
  ctx.lineTo(200 + 20 * Math.sin(t), H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(200 + 20 * Math.sin(t), H/2 - 10);
  ctx.lineTo(180 + 20 * Math.sin(t), H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(200 + 20 * Math.sin(t), H/2 - 10);
  ctx.lineTo(220 + 20 * Math.sin(t), H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(190 + 20 * Math.sin(t), H/2 - 60, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(210 + 20 * Math.sin(t), H/2 - 60, 10, 0, 2 * Math.PI);
  ctx.fill();

  // draw dog leash
  ctx.beginPath();
  ctx.moveTo(100 + 50 * Math.sin(t), H/2 + 30);
  ctx.lineTo(200 + 20 * Math.sin(t), H/2 - 10);
  ctx.stroke();

  ctx.restore();
}
